#include "engine/procgen/IJobService.hpp"
#include <cassert>
int main(){auto s=engine::jobs::create_job_service();std::string e;auto id=s->start("import",1000,e);assert(id!=0);assert(s->update(id,.5,"cook",e));assert(!s->update(id,.4,"",e));engine::jobs::JobSnapshot snap;assert(s->poll(id,snap,e));assert(snap.progress==.5);assert(s->complete(id,{{"asset","out.bin",7}},e));assert(s->poll(id,snap,e));assert(snap.state==engine::jobs::JobState::Completed&&snap.artifacts.size()==1);assert(!s->cancel(id,e));auto id2=s->start("cancel",0,e);assert(s->cancel(id2,e));assert(s->poll(id2,snap,e));assert(snap.state==engine::jobs::JobState::Cancelled);auto id3=s->start("fail",0,e);assert(s->fail(id3,"bad input",e));assert(s->poll(id3,snap,e));assert(snap.state==engine::jobs::JobState::Failed);return 0;}
